import{_ as r,o as a,a as e,b as d}from"./app.C41L12d5.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"Utils API","link":"/api/Utils-API/Utils-API"},{"text":"Utils API列表","link":"/api/Utils-API/utils_api_list"}]},"headers":[],"relativePath":"api/Utils-API/utils_api_list.md","filePath":"api/Utils-API/utils_api_list.md","lastUpdated":1788309328000}'),i={name:"api/Utils-API/utils_api_list.md"};function l(_,t,n,s,p,h){return a(),e("div",null,[...t[0]||(t[0]=[d('<div><article class="markdown-body"><h1>Utils API列表</h1><p><strong>表1</strong> C++标准库API列表</p><table><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td><a href="cpp_stdlib/algorithms/max.html">max</a></td><td>比较相同数据类型的两个数中的最大值。</td></tr><tr><td><a href="cpp_stdlib/algorithms/min.html">min</a></td><td>比较相同数据类型的两个数中的最小值。</td></tr><tr><td><a href="cpp_stdlib/math_functions/abs.html">abs</a></td><td>获取输入数据的绝对值。</td></tr><tr><td><a href="cpp_stdlib/math_functions/ceil_div.html">ceil_div</a></td><td>计算两个整数a和b相除后向上取整的结果。</td></tr><tr><td><a href="cpp_stdlib/math_functions/CeilDivision.html">CeilDivision</a></td><td>计算两个整数num1和num2相除后向上取整的结果。</td></tr><tr><td><a href="cpp_stdlib/math_functions/sqrt.html">sqrt</a></td><td>计算输入数据的平方根。</td></tr><tr><td><a href="cpp_stdlib/general_utils/integer_sequence.html">integer_sequence</a></td><td>用于生成一个整数序列。</td></tr><tr><td><a href="cpp_stdlib/container_functions/tuple.html">tuple</a></td><td>允许存储多个不同类型元素的容器。</td></tr><tr><td><a href="cpp_stdlib/container_functions/get.html">get</a></td><td>从tuple容器中提取指定位置的元素。</td></tr><tr><td><a href="cpp_stdlib/container_functions/make_tuple.html">make_tuple</a></td><td>用于便捷地创建tuple对象。</td></tr><tr><td><a href="cpp_stdlib/type_traits/is_convertible.html">is_convertible</a></td><td>在程序编译时判断两个类型之间是否可以进行隐式转换。</td></tr><tr><td><a href="cpp_stdlib/type_traits/is_base_of.html">is_base_of</a></td><td>在程序编译时判断一个类型是否为另一个类型的基类。</td></tr><tr><td><a href="cpp_stdlib/type_traits/is_same.html">is_same</a></td><td>在程序编译时判断两个类型是否完全相同。</td></tr><tr><td><a href="cpp_stdlib/type_traits/is_void.html">is_void</a></td><td>在程序编译时，检测一个类型是否为void类型。</td></tr><tr><td><a href="cpp_stdlib/type_traits/is_integral.html">is_integral</a></td><td>在程序编译时，检测一个类型是否为整数类型。</td></tr><tr><td><a href="cpp_stdlib/type_traits/is_floating_point.html">is_floating_point</a></td><td>在程序编译时，检测一个类型是否为浮点类型。</td></tr><tr><td><a href="cpp_stdlib/type_traits/is_array.html">is_array</a></td><td>在程序编译时，检测一个类型是否为数组类型。</td></tr><tr><td><a href="cpp_stdlib/type_traits/is_pointer.html">is_pointer</a></td><td>在程序编译时，判断一个类型是否为指针类型。</td></tr><tr><td><a href="cpp_stdlib/type_traits/is_reference.html">is_reference</a></td><td>在程序编译时，检测一个类型是否为引用类型。</td></tr><tr><td><a href="cpp_stdlib/type_traits/is_const.html">is_const</a></td><td>在程序编译时，检测一个类型是否为const限定的类型。</td></tr><tr><td><a href="cpp_stdlib/type_traits/remove_const.html">remove_const</a></td><td>在程序编译时，对传入的模板参数类型移除const限定符。</td></tr><tr><td><a href="cpp_stdlib/type_traits/remove_volatile.html">remove_volatile</a></td><td>在程序编译时，对传入的模板参数类型移除volatile限定符。</td></tr><tr><td><a href="cpp_stdlib/type_traits/remove_cv.html">remove_cv</a></td><td>在程序编译时，对传入的模板参数类型移除const限定符或volatile限定符，或同时移除这两种限定符。</td></tr><tr><td><a href="cpp_stdlib/type_traits/remove_reference.html">remove_reference</a></td><td>在程序编译时，从给定类型中移除引用限定符。</td></tr><tr><td><a href="cpp_stdlib/type_traits/remove_pointer.html">remove_pointer</a></td><td>在程序编译时，从给定类型中移除指针限定符。</td></tr><tr><td><a href="cpp_stdlib/type_traits/add_const.html">add_const</a></td><td>在程序编译时，为指定类型添加const限定符。</td></tr><tr><td><a href="cpp_stdlib/type_traits/add_volatile.html">add_volatile</a></td><td>在程序编译时，为指定类型添加volatile限定符。</td></tr><tr><td><a href="cpp_stdlib/type_traits/add_cv.html">add_cv</a></td><td>在程序编译时，为指定类型添加const和volatile限定符。</td></tr><tr><td><a href="cpp_stdlib/type_traits/add_pointer.html">add_pointer</a></td><td>在程序编译时，为指定类型添加指针限定符。</td></tr><tr><td><a href="cpp_stdlib/type_traits/add_lvalue_reference.html">add_lvalue_reference</a></td><td>在程序编译时，为指定类型添加左值引用限定符。</td></tr><tr><td><a href="cpp_stdlib/type_traits/add_rvalue_reference.html">add_rvalue_reference</a></td><td>在程序编译时，为指定类型添加右值引用限定符。</td></tr><tr><td><a href="cpp_stdlib/type_traits/enable_if.html">enable_if</a></td><td>在程序编译时根据某个条件启用或禁用特定的函数模板、类模板或模板特化。</td></tr><tr><td><a href="cpp_stdlib/type_traits/conditional.html">conditional</a></td><td>在程序编译时根据一个布尔条件从两个类型中选择一个类型。</td></tr><tr><td><a href="cpp_stdlib/type_traits/integral_constant.html">integral_constant</a></td><td>用于封装一个编译时常量整数值，是标准库中许多类型特性和编译时计算的基础组件。</td></tr></tbody></table><p><strong>表2</strong> 平台信息获取API列表</p><table><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td><a href="platform_info/PlatformAscendC/PlatformAscendC.html">PlatformAscendC</a></td><td>在实现Host侧的Tiling函数时，可能需要获取一些硬件平台的信息，来支撑Tiling的计算，比如获取硬件平台的核数等信息。PlatformAscendC类提供获取这些平台信息的功能。</td></tr><tr><td><a href="platform_info/PlatformAscendCManager.html">PlatformAscendCManager</a></td><td>基于Kernel Launch算子工程，通过基础调用（Kernel Launch）方式调用算子的场景下，可能需要获取硬件平台相关信息，比如获取硬件平台的核数。PlatformAscendCManager类提供获取平台信息的功能。</td></tr></tbody></table><p><strong>表3</strong> Tiling调测API列表</p><table><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td><a href="Tiling_tuning/OpTilingRegistry/OpTilingRegistry.html">OpTilingRegistry</a></td><td>OpTilingRegistry类属于context_ascendc命名空间，主要用于加载Tiling实现的动态库，并获取算子的Tiling函数指针以进行调试和验证。</td></tr><tr><td><a href="Tiling_tuning/ContextBuilder/ContextBuilder.html">ContextBuilder</a></td><td>ContextBuilder类提供一系列的API接口，支持手动构造类来验证Tiling函数以及KernelContext类用于TilingParse函数的验证。</td></tr></tbody></table><p><strong>表4</strong> Tiling模板编程API列表</p><table><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td><a href="Tiling_template_programming/template_params_definition.html">模板参数定义</a></td><td>通过该类接口进行模板参数ASCENDC_TPL_ARGS_DECL和模板参数组合ASCENDC_TPL_ARGS_SEL（即可使用的模板）的定义。</td></tr><tr><td><a href="Tiling_template_programming/GET_TPL_TILING_KEY.html">GET_TPL_TILING_KEY</a></td><td>Tiling模板编程时，开发者通过调用此接口自动生成TilingKey。该接口将传入的模板参数通过定义的位宽，转成二进制，按照顺序组合后转成uint64数值，即TilingKey。</td></tr><tr><td><a href="Tiling_template_programming/ASCENDC_TPL_SEL_PARAM.html">ASCENDC_TPL_SEL_PARAM</a></td><td>Tiling模板编程时，开发者通过调用此接口自动生成并配置TilingKey。</td></tr></tbody></table><p><strong>表5</strong> RTC API列表</p><table><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td><a href="RTC/aclrtcCompileProg.html">aclrtcCompileProg</a></td><td>编译接口，编译指定的程序。</td></tr><tr><td><a href="RTC/aclrtcCreateProg.html">aclrtcCreateProg</a></td><td>通过给定的参数，创建编译程序的实例。</td></tr><tr><td><a href="RTC/aclrtcDestroyProg.html">aclrtcDestroyProg</a></td><td>销毁编译程序的实例。</td></tr><tr><td><a href="RTC/aclrtcGetBinData.html">aclrtcGetBinData</a></td><td>获取编译后的二进制数据。</td></tr><tr><td><a href="RTC/aclrtcGetBinDataSize.html">aclrtcGetBinDataSize</a></td><td>获取编译的二进制数据大小。用于在<a href="RTC/aclrtcGetBinData.html">aclrtcGetBinData</a>获取二进制数据时分配对应大小的内存空间。</td></tr><tr><td><a href="RTC/aclrtcGetCompileLogSize.html">aclrtcGetCompileLogSize</a></td><td>获取编译日志的大小。用于在<a href="RTC/aclrtcGetCompileLog.html">aclrtcGetCompileLog</a>获取日志内容时分配对应大小的内存空间。</td></tr><tr><td><a href="RTC/aclrtcGetCompileLog.html">aclrtcGetCompileLog</a></td><td>获取编译日志的内容，以字符串形式保存。</td></tr></tbody></table><p><strong>表6</strong> log API列表</p><table><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td><a href="log/ASC_CPU_LOG.html">ASC_CPU_LOG</a></td><td>提供Host侧打印Log的功能。开发者可以在算子的TilingFunc代码中使用ASC_CPU_LOG_XXX接口来输出相关内容。</td></tr></tbody></table><p><strong>表7</strong> 调测接口列表</p><table><thead><tr><th>接口名</th><th>功能描述</th></tr></thead><tbody><tr><td><a href="tuning_interface/printf.html">printf</a></td><td>在算子核函数（Kernel）侧的实现代码中，需要输出日志信息时，调用printf接口打印相关内容。</td></tr><tr><td><a href="tuning_interface/assert.html">assert/ascendc_assert</a></td><td>用于在算子核函数（Kernel）中检查指定条件。条件不成立时，接口打印断言失败信息并触发异常。</td></tr><tr><td><a href="tuning_interface/__trap.html">__trap</a></td><td>在SIMT VF实现代码中调用此接口会中断算子的运行。</td></tr><tr><td><a href="tuning_interface/clock.html">clock</a></td><td>本接口在SIMT VF调试场景中提供Clock时间戳功能，用于记录从程序启动到接口调用时刻所经历的时钟周期数（Cycle Count），便于精确分析执行延迟和性能瓶颈。</td></tr><tr><td><a href="tuning_interface/asc_dump.html">asc_dump</a></td><td>将对应内存上的数据打印出来，同时支持打印自定义的附加信息（仅支持uint32_t类型的信息），比如打印当前行号等。</td></tr><tr><td><a href="tuning_interface/asc_time_stamp.html">asc_time_stamp</a></td><td>提供时间戳打点功能，用于在算子核函数（Kernel）代码中标记关键执行点。</td></tr><tr><td><a href="tuning_interface/asc_prof_start.html">asc_prof_start</a></td><td>设置性能数据采集信号启动，和asc_prof_stop配合使用，用于指定需要调优的代码段范围。</td></tr><tr><td><a href="tuning_interface/asc_prof_stop.html">asc_prof_stop</a></td><td>设置性能数据采集信号停止，和asc_prof_start配合使用，用于指定需要调优的代码段范围。</td></tr><tr><td><a href="tuning_interface/asc_mark_stamp.html">asc_mark_stamp</a></td><td>在算子执行过程中标记特定位置，便于后期通过流水图分析代码执行路径与性能热点。</td></tr><tr><td><a href="tuning_interface/TRACE_START.html">TRACE_START</a></td><td>通过仿真器进行算子性能仿真时，可对算子任意运行阶段打点，从而分析不同指令的流水图，以便进一步性能调优。</td></tr><tr><td><a href="tuning_interface/TRACE_STOP.html">TRACE_STOP</a></td><td>通过仿真器进行算子性能仿真时，可对算子任意运行阶段打点，从而分析不同指令的流水图，以便进一步性能调优。</td></tr></tbody></table></article></div>',1)])])}const m=r(i,[["render",l]]);export{c as __pageData,m as default};
